CREATE TABLE IF NOT EXISTS namespace_policy(namespace text PRIMARY KEY REFERENCES namespaces(id), root_policy text NOT NULL);
CREATE TABLE IF NOT EXISTS principal_authorities(namespace text NOT NULL, principal text NOT NULL, authority text NOT NULL, PRIMARY KEY(namespace,principal), FOREIGN KEY(namespace,principal) REFERENCES principals(namespace,id));
CREATE TABLE IF NOT EXISTS staged_revisions(upload text NOT NULL REFERENCES upload_sessions(id), revision text NOT NULL, descriptor bytea NOT NULL CHECK(octet_length(descriptor)<=16777216), PRIMARY KEY(upload,revision));
CREATE TABLE IF NOT EXISTS revisions(namespace text NOT NULL REFERENCES namespaces(id), revision text NOT NULL, descriptor bytea NOT NULL, PRIMARY KEY(namespace,revision));
CREATE TABLE IF NOT EXISTS branches(namespace text NOT NULL REFERENCES namespaces(id), name text NOT NULL, revision text NOT NULL, head text NOT NULL, PRIMARY KEY(namespace,name), FOREIGN KEY(namespace,revision) REFERENCES revisions(namespace,revision));
CREATE TABLE IF NOT EXISTS views(id text PRIMARY KEY, namespace text NOT NULL, branch text NOT NULL, credential text NOT NULL REFERENCES credentials(id), principal text NOT NULL, replica text NOT NULL, full_revision text NOT NULL, head text NOT NULL, projected_revision text NOT NULL, descriptor bytea NOT NULL, FOREIGN KEY(namespace,full_revision) REFERENCES revisions(namespace,revision));
CREATE TABLE IF NOT EXISTS operations(namespace text NOT NULL, replica text NOT NULL, operation text NOT NULL, principal text NOT NULL, credential text NOT NULL, kind text NOT NULL, digest text NOT NULL, request text NOT NULL, result text NOT NULL, status integer NOT NULL, branch text NOT NULL, view_id text, receipt text NOT NULL UNIQUE, submitted_revision text NOT NULL, derived_revision text, PRIMARY KEY(namespace,replica,operation), FOREIGN KEY(namespace,derived_revision) REFERENCES revisions(namespace,revision));
CREATE TABLE IF NOT EXISTS revision_objects(namespace text NOT NULL, revision text NOT NULL, object_id text NOT NULL, generation text NOT NULL, PRIMARY KEY(namespace,revision,object_id), FOREIGN KEY(namespace,revision) REFERENCES revisions(namespace,revision), FOREIGN KEY(namespace,object_id,generation) REFERENCES objects(namespace,object_id,generation));
CREATE TABLE IF NOT EXISTS changes(sequence bigserial PRIMARY KEY, namespace text NOT NULL, branch text NOT NULL, head text NOT NULL, paths text[] NOT NULL, UNIQUE(namespace,head));
CREATE INDEX IF NOT EXISTS changes_branch ON changes(namespace,branch,sequence);
